/** Consent categories. `essential` is always allowed and never blocked. */
export type Category = "essential" | "functional" | "analytics" | "marketing";

/** The notice shown to a visitor, chosen from their location. */
export type Framework = "gdpr" | "ccpa" | "dpdpa" | "generic";

export type Categories = Record<Category, boolean>;

export interface ConsentState {
  framework: Framework;
  categories: Categories;
  /** true once the visitor has made a choice for the current config version */
  decided: boolean;
  /** random id generated by the script, never derived from personal data */
  visitorId: string;
  /** language the notice is shown in, e.g. "en" or "hi" */
  language: string;
}

export type ConsentEvent = "change" | "ready";

/** The `window.PlainConsent` API exposed by plain-consent.js. */
export interface PlainConsentApi {
  /** script version, e.g. "1.0.0" */
  version: string;
  get(): ConsentState;
  acceptAll(): void;
  rejectAll(): void;
  /** turn categories on or off; recorded as a custom choice */
  set(partial: Partial<Categories>): void;
  /** open the preferences panel */
  open(): void;
  /** forget the choice, record the withdrawal and show the banner again */
  revoke(): void;
  /** "ready" fires once the site's settings have loaded (at once if they already have); returns an unsubscribe function */
  on(event: ConsentEvent, fn: (state: ConsentState) => void): () => void;
  push(fn: (api: PlainConsentApi) => void): void;
  /** show the notice in one of the site's languages (e.g. "hi", "ta"); "" for the default */
  setLanguage(code: string): void;
}

export interface LoadOptions {
  /** Your public site key from the dashboard's Install page (pk_ followed by 16 characters). */
  siteKey: string;
  /** Script URL. Defaults to https://www.theplaintheory.in/sdk/plain-consent.js, or `{origin of apiUrl}/sdk/plain-consent.js` when `apiUrl` is set. */
  src?: string;
  /** API base for receipts and events (`data-api`). Defaults to the script's origin + /api/v1. */
  apiUrl?: string;
  /** Published config URL (`data-config-url`), e.g. on the CDN. Defaults to `{apiUrl}/config/{siteKey}`. */
  configUrl?: string;
  /** Google Consent Mode v2 (`data-gcm`): set consent defaults for Google tags before the config arrives. */
  gcm?: boolean;
  /** Allow `?plain_country=` location overrides outside localhost (`data-debug`). */
  debug?: boolean;
  /** Resolve the load promise after this many ms even if the config hasn't arrived. Default 8000. */
  readyTimeoutMs?: number;
  /** Optional CSP nonce for the injected script tag. */
  nonce?: string;
}
